import{_ as a,c as t,o as i,a5 as r}from"./chunks/framework.BTBXp1_p.js";const u=JSON.parse('{"title":"ADR-003: Stable Client Metadata Across DCR","description":"","frontmatter":{},"headers":[],"relativePath":"adr/003-stable-client-metadata.md","filePath":"adr/003-stable-client-metadata.md","lastUpdated":1769357072000}'),s={name:"adr/003-stable-client-metadata.md"};function n(o,e,l,d,c,h){return i(),t("div",null,[...e[0]||(e[0]=[r('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /oauth-callback/adr/003-stable-client-metadata.md for this page in Markdown format</div><h1 id="adr-003-stable-client-metadata-across-dcr" tabindex="-1">ADR-003: Stable Client Metadata Across DCR <a class="header-anchor" href="#adr-003-stable-client-metadata-across-dcr" aria-label="Permalink to “ADR-003: Stable Client Metadata Across DCR”">​</a></h1><p><strong>Status:</strong> Accepted <strong>Date:</strong> 2025-01-25 <strong>Tags:</strong> oauth, dcr, security</p><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to “Problem”">​</a></h2><ul><li>During Dynamic Client Registration (DCR), the authorization server may return different capabilities than requested (e.g., <code>token_endpoint_auth_method</code>).</li><li>If <code>clientMetadata</code> adapts to DCR responses, subsequent token requests may fail when the AS caches the original registration metadata.</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ul><li><code>clientMetadata</code> is immutable after construction.</li><li><code>token_endpoint_auth_method</code> is determined at construction: <code>client_secret_post</code> if <code>clientSecret</code> is provided, <code>none</code> otherwise. DCR responses never change this value.</li><li>DCR credentials (<code>client_id</code>, <code>client_secret</code>) are stored separately and never mutate the auth method.</li></ul><h2 id="alternatives-brief" tabindex="-1">Alternatives (brief) <a class="header-anchor" href="#alternatives-brief" aria-label="Permalink to “Alternatives (brief)”">​</a></h2><ul><li><strong>Dynamic metadata evolution</strong> — Adapting to DCR responses seems flexible but causes cache mismatches with AS that remember original registration.</li><li><strong>Per-request method detection</strong> — Adds complexity and non-deterministic behavior across retries.</li></ul><h2 id="impact" tabindex="-1">Impact <a class="header-anchor" href="#impact" aria-label="Permalink to “Impact”">​</a></h2><ul><li>Positive: Predictable behavior with all AS implementations; eliminates cache-related auth failures.</li><li>Negative/Risks: None identified; the fixed method (<code>client_secret_post</code>) has universal support.</li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to “Links”">​</a></h2><ul><li>Code: <code>src/auth/browser-auth.ts</code></li><li>Related ADRs: ADR-001 (No Refresh Tokens), ADR-002 (Immediate Token Exchange)</li></ul>',13)])])}const b=a(s,[["render",n]]);export{u as __pageData,b as default};
